const express = require('express');
const { pool, logAudit } = require('../db');
const { authenticateToken, requireRole } = require('../middleware/auth');
const { runForDate, todayLocal, shiftDate } = require('../lib/dailyLists');
const { validateDr7ForCollector, validateResourceEligibility } = require('../lib/collectionValidation');
const { resolveRecipientForEmployee, createStaffNotification, logNotificationFailure } = require('../lib/staffNotifications');

// Daily lists ("Today's list") — read + supervisor edits of the auto batches
// generated by lib/dailyLists.js. Same scoping as batches.js: gudoomiye and
// zone_accountant only ever see / touch their own district.
const router = express.Router();
router.use(authenticateToken);

const VIEW_ROLES = ['admin', 'gudoomiye', 'zone_accountant'];
const WRITE_ROLES = ['admin', 'gudoomiye'];
const ZONE_SCOPED_ROLES = ['gudoomiye', 'zone_accountant'];
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
const err = (res, status, code, message, extra = {}) => res.status(status).json({ error: { message, code }, ...extra });

function parseStrictId(raw) {
  if (!/^\d+$/.test(String(raw ?? ''))) return null;
  return parseInt(raw, 10);
}

async function resolveUserZoneId(user) {
  if (!ZONE_SCOPED_ROLES.includes((user.role || '').toLowerCase())) return null;
  if (!user.zone) return -1; // scoped role without a district sees nothing
  const r = await pool.query('SELECT id FROM zones WHERE name = $1', [user.zone]);
  return r.rows[0]?.id ?? -1;
}

// "Group › District › Zone › Sub Zone" (same order as invoices/map).
const PATH_SQL = `concat_ws(' › ', NULLIF(COALESCE(g.name, g.code), ''), NULLIF(z.name, ''), NULLIF(COALESCE(gz.name, gz.code), ''), NULLIF(COALESCE(r.name, r.code), ''))`;

// GET /api/v2/daily-lists?date=YYYY-MM-DD — one card per Sub Zone that has a
// list that day (or is scheduled that weekday but got none, with the reason).
router.get('/', requireRole(...VIEW_ROLES), async (req, res) => {
  try {
    const local = await todayLocal();
    const date = req.query.date || local.date;
    if (!DATE_RE.test(date)) return err(res, 400, 'VALIDATION', 'date must be YYYY-MM-DD.');
    const zoneId = await resolveUserZoneId(req.user);
    const params = [date];
    let scope = '';
    if (zoneId !== null) { params.push(zoneId); scope = `AND g.zone_id = $${params.length}`; }
    const weekday = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'][new Date(date + 'T00:00:00Z').getUTCDay()];
    params.push(weekday);
    const wdIdx = params.length;

    const rows = (await pool.query(
      `SELECT r.id AS route_id, COALESCE(r.name, r.code) AS route_name, r.work_days, r.collector_user_id, r.truck_id AS default_truck_id,
              g.id AS group_id, COALESCE(g.name, g.code) AS group_name, g.code AS group_code, z.id AS zone_id, z.name AS district_name,
              COALESCE(gz.name, gz.code) AS group_zone_name, ${PATH_SQL} AS path,
              COALESCE(u.full_name, u.username) AS default_collector_name,
              COALESCE(bl.batches, '[]'::json) AS batches,
              (SELECT COUNT(*)::int FROM customers c WHERE c.route_id = r.id AND c.status = 'active') AS customer_count
       FROM routes r
       JOIN groups g ON g.id = r.group_id
       JOIN zones z ON z.id = g.zone_id
       LEFT JOIN group_zones gz ON gz.id = r.group_zone_id
       LEFT JOIN v2_users u ON u.id = r.collector_user_id
       LEFT JOIN LATERAL (
         SELECT json_agg(json_build_object(
           'id', b.id, 'batch_code', b.batch_code, 'status', b.status, 'customer_type', b.customer_type, 'commercial_shift', b.commercial_shift,
           'total', p.total, 'serviced', p.serviced, 'missed', p.missed, 'pending', p.pending, 'skipped', p.skipped,
           'carried', (SELECT COUNT(*)::int FROM batch_customers x WHERE x.batch_id = b.id AND x.carried_over_from IS NOT NULL),
           'collector', (SELECT json_build_object('employee_id', e.id, 'name', e.name, 'user_id', e.user_id)
                         FROM tasks t JOIN task_resources tr ON tr.task_id = t.id AND tr.resource_type = 'collector'
                         JOIN employees e ON e.id = tr.resource_id WHERE t.batch_id = b.id ORDER BY tr.id LIMIT 1),
           'truck', (SELECT json_build_object('id', tk.id, 'plate_number', tk.plate_number)
                     FROM tasks t JOIN task_resources tr ON tr.task_id = t.id AND tr.resource_type = 'truck'
                     JOIN trucks tk ON tk.id = tr.resource_id WHERE t.batch_id = b.id ORDER BY tr.id LIMIT 1)
         ) ORDER BY b.customer_type, b.commercial_shift NULLS FIRST, b.id) AS batches
         FROM batches b JOIN batch_progress p ON p.batch_id = b.id
         WHERE b.auto_generated AND b.route_id = r.id AND b.start_date = $1::date
       ) bl ON TRUE
       WHERE (bl.batches IS NOT NULL OR (r.status = 'active' AND g.status = 'active' AND COALESCE(r.work_days, '[]'::jsonb) ? $${wdIdx}))
         ${scope}
       ORDER BY COALESCE(g.name, g.code), g.id, z.name, COALESCE(gz.name, gz.code) NULLS LAST, COALESCE(r.name, r.code), r.id`,
      params)).rows;

    const lists = rows.filter((row) => (row.batches && row.batches.length) || row.customer_count > 0).map((row) => {
      const batches = row.batches || [];
      const sum = (k) => batches.reduce((a, b) => a + Number(b[k] || 0), 0);
      const counts = { total: sum('total'), serviced: sum('serviced'), missed: sum('missed'), pending: sum('pending'), skipped: sum('skipped'), carried: sum('carried') };
      const firstCollector = batches.find((b) => b.collector)?.collector || null;
      const firstTruck = batches.find((b) => b.truck)?.truck || null;
      let notGenerated = null;
      if (batches.length === 0) notGenerated = row.collector_user_id ? 'not_generated' : 'no_collector';
      return {
        route_id: row.route_id, route_name: row.route_name, group_id: row.group_id, group_name: row.group_name, zone_id: row.zone_id,
        district_name: row.district_name, group_zone_name: row.group_zone_name, path: row.path, work_days: row.work_days || [],
        collector: firstCollector || (row.collector_user_id ? { user_id: row.collector_user_id, name: row.default_collector_name } : null),
        truck: firstTruck, default_truck_id: row.default_truck_id, batches, counts, not_generated: notGenerated,
      };
    });
    const lastRun = (await pool.query(
      `SELECT id, to_char(run_date, 'YYYY-MM-DD') AS run_date, started_at, finished_at, created_batches, customers, closed_batches, skipped, error, triggered_by
       FROM daily_list_runs ORDER BY id DESC LIMIT 1`)).rows[0] || null;
    res.json({ data: { date, today: local.date, weekday, lists, last_run: lastRun } });
  } catch (e) {
    err(res, 500, 'INTERNAL', 'Failed to load daily lists.');
  }
});

// GET /api/v2/daily-lists/warnings — Sub Zones without work days, and active
// customers without a Sub Zone (neither is ever put on a list).
router.get('/warnings', requireRole(...VIEW_ROLES), async (req, res) => {
  try {
    const zoneId = await resolveUserZoneId(req.user);
    const params = [];
    let scopeG = '';
    let scopeC = '';
    if (zoneId !== null) { params.push(zoneId); scopeG = 'AND g.zone_id = $1'; scopeC = 'AND c.zone_id = $1'; }
    const subzones = (await pool.query(
      `SELECT r.id, COALESCE(r.name, r.code) AS name, r.group_id, ${PATH_SQL} AS path, COALESCE(u.full_name, u.username) AS collector_name,
              (SELECT COUNT(*)::int FROM customers c WHERE c.route_id = r.id AND c.status = 'active') AS customer_count
       FROM routes r JOIN groups g ON g.id = r.group_id JOIN zones z ON z.id = g.zone_id
       LEFT JOIN group_zones gz ON gz.id = r.group_zone_id LEFT JOIN v2_users u ON u.id = r.collector_user_id
       WHERE r.status = 'active' AND g.status = 'active' AND jsonb_array_length(COALESCE(r.work_days, '[]'::jsonb)) = 0 ${scopeG}
       ORDER BY path, r.id`, params)).rows;
    const customers = (await pool.query(
      `SELECT c.id, c.customer_number, c.name, c.customer_type, c.zone_id, z.name AS district_name, COALESCE(g.name, g.code) AS group_name
       FROM customers c JOIN zones z ON z.id = c.zone_id LEFT JOIN groups g ON g.id = c.group_id
       WHERE c.status = 'active' AND c.route_id IS NULL ${scopeC}
       ORDER BY c.id LIMIT 500`, params)).rows;
    const customerTotal = (await pool.query(`SELECT COUNT(*)::int AS n FROM customers c WHERE c.status = 'active' AND c.route_id IS NULL ${scopeC}`, params)).rows[0].n;
    res.json({ data: { subzones_without_days: subzones, customers_without_subzone: customers, customers_without_subzone_total: customerTotal } });
  } catch (e) {
    err(res, 500, 'INTERNAL', 'Failed to load daily list warnings.');
  }
});

// GET /api/v2/daily-lists/options?zone_id= — collectors (with an employee
// record) and non-retired trucks usable in a district, for the reassign and
// Sub Zone default-truck selects (GET /users is admin-only). Scoped roles
// always get their own district.
router.get('/options', requireRole(...VIEW_ROLES), async (req, res) => {
  try {
    let zoneId = await resolveUserZoneId(req.user);
    if (zoneId === null) {
      zoneId = req.query.zone_id ? parseStrictId(req.query.zone_id) : null;
      if (req.query.zone_id && zoneId === null) return err(res, 400, 'VALIDATION', 'Invalid zone_id.');
    }
    const params = [];
    let cz = '';
    let tz = '';
    if (zoneId !== null) { params.push(zoneId); cz = 'AND z.id = $1'; tz = 'AND (t.zone_id IS NULL OR t.zone_id = $1)'; }
    const collectors = (await pool.query(
      `SELECT u.id AS user_id, COALESCE(u.full_name, u.username) AS name, z.id AS zone_id, e.id AS employee_id, e.collector_type, e.commercial_shift
       FROM v2_users u JOIN zones z ON z.name = u.zone JOIN employees e ON e.user_id = u.id
       WHERE u.role = 'collector' AND u.is_active AND e.status <> 'archived' ${cz}
       ORDER BY name`, params)).rows;
    const trucks = (await pool.query(
      `SELECT t.id, t.plate_number, t.model, t.zone_id, t.status FROM trucks t WHERE t.status <> 'retired' ${tz} ORDER BY t.plate_number`, params)).rows;
    res.json({ data: { collectors, trucks } });
  } catch (e) {
    err(res, 500, 'INTERNAL', 'Failed to load options.');
  }
});

// POST /api/v2/daily-lists/run {date?} — admin. Today by default; the last
// 7 days are allowed (catch-up), never a future day (closing would end
// today's lists early).
router.post('/run', requireRole('admin'), async (req, res) => {
  try {
    const local = await todayLocal();
    const date = req.body?.date || local.date;
    if (!DATE_RE.test(date)) return err(res, 400, 'VALIDATION', 'date must be YYYY-MM-DD.');
    if (date > local.date) return err(res, 400, 'VALIDATION', 'A daily list cannot be generated for a future day.');
    if (date < shiftDate(local.date, -7)) return err(res, 400, 'VALIDATION', 'Only the last 7 days can be generated.');
    const result = await runForDate({ date, triggeredBy: req.user.id });
    res.json({ data: result });
  } catch (e) {
    err(res, 500, 'INTERNAL', 'Daily list run failed: ' + (e.message || e));
  }
});

// Shared guard for the edit endpoints: an auto batch, in scope, today or later, still open.
async function loadEditableBatch(req, res) {
  const id = parseStrictId(req.params.batchId);
  if (id === null) { err(res, 400, 'VALIDATION', 'Invalid batch id.'); return null; }
  const r = await pool.query(`SELECT * FROM batches WHERE id = $1`, [id]);
  const b = r.rows[0];
  if (!b || !b.auto_generated) { err(res, 404, 'NOT_FOUND', 'Daily list not found.'); return null; }
  const zoneId = await resolveUserZoneId(req.user);
  if (zoneId !== null && zoneId !== b.zone_id) { err(res, 403, 'FORBIDDEN', 'You do not have access to this daily list.'); return null; }
  const local = await todayLocal();
  if ((b.end_date || b.start_date) < local.date) { err(res, 409, 'CONFLICT', 'Only today\'s or a future list can be edited.'); return null; }
  if (['completed', 'cancelled'].includes(b.status)) { err(res, 409, 'CONFLICT', `This list is ${b.status}.`); return null; }
  return b;
}

// POST /api/v2/daily-lists/:batchId/customers {customer_id}
router.post('/:batchId/customers', requireRole(...WRITE_ROLES), async (req, res) => {
  try {
    const b = await loadEditableBatch(req, res);
    if (!b) return;
    const customerId = parseStrictId(req.body?.customer_id);
    if (customerId === null) return err(res, 400, 'VALIDATION', 'customer_id is required.');
    const c = (await pool.query('SELECT id, zone_id, status, customer_type, COALESCE(commercial_shift, \'day\') AS shift FROM customers WHERE id = $1', [customerId])).rows[0];
    if (!c) return err(res, 404, 'NOT_FOUND', 'Customer not found.');
    if (c.zone_id !== b.zone_id) return err(res, 400, 'VALIDATION', 'This customer is not in this list\'s district.');
    if (c.status !== 'active') return err(res, 400, 'VALIDATION', 'Only active customers can be added.');
    if (c.customer_type !== b.customer_type || (b.customer_type === 'commercial' && c.shift !== b.commercial_shift)) {
      return err(res, 400, 'DR7_BLOCK', `This customer does not match this list's customer type (${b.customer_type}${b.commercial_shift ? ' ' + b.commercial_shift : ''}).`);
    }
    const client = await pool.connect();
    try {
      await client.query('BEGIN');
      await client.query('SELECT id FROM batches WHERE id = $1 FOR UPDATE', [b.id]);
      const dup = await client.query(
        `SELECT b.id FROM batch_customers bc JOIN batches b ON b.id = bc.batch_id
         WHERE bc.customer_id = $1 AND b.status <> 'cancelled'
           AND (bc.status = 'pending' OR (b.start_date <= $2::date AND COALESCE(b.end_date, b.start_date) >= $2::date)) LIMIT 1`,
        [customerId, b.start_date]);
      if (dup.rows[0]) { await client.query('ROLLBACK'); return err(res, 409, 'CONFLICT', 'This customer is already on a list for that day (or pending in another batch).'); }
      const ins = await client.query(`INSERT INTO batch_customers (batch_id, customer_id, status) VALUES ($1, $2, 'pending') RETURNING *`, [b.id, customerId]);
      await client.query('UPDATE batches SET total_customers = total_customers + 1, updated_at = NOW() WHERE id = $1', [b.id]);
      await client.query('COMMIT');
      await logAudit({ actorId: req.user.id, actorUsername: req.user.username, action: 'daily_list.add_customer', entityType: 'batch_customer', entityId: ins.rows[0].id, before: null, after: ins.rows[0] });
      res.status(201).json({ data: ins.rows[0] });
    } catch (e) {
      await client.query('ROLLBACK').catch(() => {});
      if (e.code === '23505') return err(res, 409, 'CONFLICT', 'This customer is already on a list for that day (or pending in another batch).');
      throw e;
    } finally {
      client.release();
    }
  } catch (e) {
    err(res, 500, 'INTERNAL', 'Failed to add customer.');
  }
});

// DELETE /api/v2/daily-lists/:batchId/customers/:customerId — pending only.
router.delete('/:batchId/customers/:customerId', requireRole(...WRITE_ROLES), async (req, res) => {
  try {
    const b = await loadEditableBatch(req, res);
    if (!b) return;
    const customerId = parseStrictId(req.params.customerId);
    if (customerId === null) return err(res, 400, 'VALIDATION', 'Invalid customer id.');
    const client = await pool.connect();
    try {
      await client.query('BEGIN');
      const bc = (await client.query('SELECT * FROM batch_customers WHERE batch_id = $1 AND customer_id = $2 FOR UPDATE', [b.id, customerId])).rows[0];
      if (!bc) { await client.query('ROLLBACK'); return err(res, 404, 'NOT_FOUND', 'This customer is not on this list.'); }
      if (bc.status !== 'pending') { await client.query('ROLLBACK'); return err(res, 409, 'CONFLICT', `This customer is already ${bc.status}.`); }
      await client.query('DELETE FROM batch_customers WHERE id = $1', [bc.id]);
      await client.query('UPDATE batches SET total_customers = GREATEST(total_customers - 1, 0), updated_at = NOW() WHERE id = $1', [b.id]);
      await client.query('COMMIT');
      await logAudit({ actorId: req.user.id, actorUsername: req.user.username, action: 'daily_list.remove_customer', entityType: 'batch_customer', entityId: bc.id, before: bc, after: null });
      res.json({ data: { success: true } });
    } catch (e) {
      await client.query('ROLLBACK').catch(() => {});
      throw e;
    } finally {
      client.release();
    }
  } catch (e) {
    err(res, 500, 'INTERNAL', 'Failed to remove customer.');
  }
});

// PUT /api/v2/daily-lists/:batchId/assignment {collector_user_id?, truck_id?}
// Reassigns the list for that day only (the Sub Zone's defaults are unchanged).
router.put('/:batchId/assignment', requireRole(...WRITE_ROLES), async (req, res) => {
  try {
    const b = await loadEditableBatch(req, res);
    if (!b) return;
    const body = req.body || {};
    if (body.collector_user_id === undefined && body.truck_id === undefined) return err(res, 400, 'VALIDATION', 'collector_user_id or truck_id is required.');

    let employeeId;
    if (body.collector_user_id !== undefined) {
      const uid = parseStrictId(body.collector_user_id);
      if (uid === null) return err(res, 400, 'VALIDATION', 'collector_user_id must be a valid user id.');
      const u = (await pool.query(
        `SELECT u.role, u.is_active, z.id AS zone_id, e.id AS employee_id FROM v2_users u LEFT JOIN zones z ON z.name = u.zone
         LEFT JOIN employees e ON e.user_id = u.id WHERE u.id = $1`, [uid])).rows[0];
      if (!u || u.role !== 'collector') return err(res, 400, 'VALIDATION', 'collector_user_id must reference a user with the collector role.');
      if (!u.is_active) return err(res, 400, 'VALIDATION', 'That collector account is inactive.');
      if (u.zone_id !== b.zone_id) return err(res, 400, 'VALIDATION', 'That collector does not work in this district.');
      if (!u.employee_id) return err(res, 400, 'VALIDATION', 'That collector has no employee record.');
      const dr7 = await validateDr7ForCollector(u.employee_id, b);
      if (!dr7.ok) return err(res, 409, dr7.code, dr7.error);
      employeeId = u.employee_id;
    }
    let truckId;
    if (body.truck_id !== undefined) {
      if (body.truck_id === null) truckId = null;
      else {
        truckId = parseStrictId(body.truck_id);
        if (truckId === null) return err(res, 400, 'VALIDATION', 'truck_id must be a valid truck id or null.');
        const t = (await pool.query('SELECT zone_id FROM trucks WHERE id = $1', [truckId])).rows[0];
        const elig = await validateResourceEligibility('truck', truckId);
        if (!elig.ok) return err(res, 400, elig.code, elig.error);
        if (t.zone_id !== null && t.zone_id !== b.zone_id) return err(res, 400, 'VALIDATION', 'That truck does not belong to this district.');
      }
    }

    const reason = 'Daily list reassignment';
    const client = await pool.connect();
    let after;
    try {
      await client.query('BEGIN');
      await client.query('SELECT id FROM batches WHERE id = $1 FOR UPDATE', [b.id]);
      let task = (await client.query('SELECT id FROM tasks WHERE batch_id = $1 ORDER BY id LIMIT 1', [b.id])).rows[0];
      if (!task) task = (await client.query(`INSERT INTO tasks (batch_id, status, scheduled_at) VALUES ($1, 'pending', $2::date) RETURNING id`, [b.id, b.start_date])).rows[0];
      const replace = async (type, newId) => {
        const old = await client.query('DELETE FROM task_resources WHERE task_id = $1 AND resource_type = $2 RETURNING resource_id', [task.id, type]);
        for (const o of old.rows) {
          await client.query(`INSERT INTO task_resource_history (task_id, resource_type, resource_id, action, reason, performed_by) VALUES ($1,$2,$3,'removed',$4,$5)`, [task.id, type, o.resource_id, reason, req.user.id]);
        }
        if (newId !== null) {
          await client.query(`INSERT INTO task_resources (task_id, resource_type, resource_id, role_note) VALUES ($1,$2,$3,'daily list')`, [task.id, type, newId]);
          await client.query(`INSERT INTO task_resource_history (task_id, resource_type, resource_id, action, performed_by) VALUES ($1,$2,$3,'assigned',$4)`, [task.id, type, newId, req.user.id]);
        }
        return old.rows.map((o) => o.resource_id);
      };
      const removedCollectors = employeeId !== undefined ? await replace('collector', employeeId) : [];
      if (truckId !== undefined) await replace('truck', truckId);
      await client.query(`UPDATE batches SET status = 'assigned', assigned_at = COALESCE(assigned_at, NOW()), updated_at = NOW() WHERE id = $1 AND status = 'draft'
        AND EXISTS (SELECT 1 FROM task_resources tr WHERE tr.task_id = $2 AND tr.resource_type = 'collector')`, [b.id, task.id]);
      after = (await client.query('SELECT * FROM batches WHERE id = $1', [b.id])).rows[0];
      await client.query('COMMIT');
      after = { ...after, collector_employee_id: employeeId, truck_id: truckId, removed_collectors: removedCollectors };
    } catch (e) {
      await client.query('ROLLBACK').catch(() => {});
      throw e;
    } finally {
      client.release();
    }
    await logAudit({ actorId: req.user.id, actorUsername: req.user.username, action: 'daily_list.reassign', entityType: 'batch', entityId: b.id, before: b, after });
    if (employeeId !== undefined && !after.removed_collectors.includes(employeeId)) {
      try {
        const recipientId = await resolveRecipientForEmployee(employeeId);
        if (recipientId !== null) {
          await createStaffNotification({ recipientId, eventType: 'task_resource.assign', title: 'New task assignment',
            body: `You've been assigned today's list ${b.batch_code}.`, entityType: 'batch', entityId: b.id });
        }
      } catch (e) { logNotificationFailure('daily_list.reassign', e); }
    }
    res.json({ data: after });
  } catch (e) {
    err(res, 500, 'INTERNAL', 'Failed to reassign the list.');
  }
});

module.exports = router;
